PokiServices.CommercialBreak = function() {
	
		SoundSystem.MuteMusic();
		Utils.DO_NOT_UPDATE = true;
		
		PokiSDK.commercialBreak().then(
			() => {
				Utils.DO_NOT_UPDATE = false;
				SoundSystem.UnmuteMusic();
				console.log("Commercial break finished, proceeding to game");
				PokiSDK.gameplayStart();
				
			}
		); ;
};
PokiServices.RewardBreak = function() {
	
		//PokiSDK.gameplayStop();
		SoundSystem.MuteMusic();
		Utils.DO_NOT_UPDATE = true;
		
		
		PokiSDK.rewardedBreak().then(
			(success) => {
				if(success) {
				  
					// video was displayed, give reward
					if ( Utils.REWARD_TYPE == 0 )
						Utils.REWARD_RESULT = 1;
					
					
				  Utils.DO_NOT_UPDATE = false;
				  SoundSystem.UnmuteMusic();
				}
				else {
				  
					// video not displayed, should probably not give reward
					Utils.AD_BLOCKER_ON = true;
					
					if( Utils.REWARD_TYPE == 0 )
						Utils.REWARD_RESULT = -1;
				
						
					Utils.DO_NOT_UPDATE = false;
					SoundSystem.UnmuteMusic();
				}
			
				if( Utils.AD_BLOCKER_ON == false )
					PokiSDK.gameplayStart();
				
			}
		); ;
};
PokiServices.RewardGameOverBreak = function() {
	
		//PokiSDK.gameplayStop();
		SoundSystem.MuteMusic();
		Utils.DO_NOT_UPDATE = true;
		// show menu
		// when users selects rewarded option, trigger rewarded break
		PokiSDK.rewardedBreak().then(
			(success) => {
				if(success) {
				  // video was displayed, give reward
				  Utils.REWARD_GIVEN = true;
				  Utils.DO_NOT_UPDATE = false;
				  SoundSystem.UnmuteMusic();
				}
				else {
				  // video not displayed, should probably not give reward
				  Utils.DO_NOT_UPDATE = false;
				  SoundSystem.UnmuteMusic();
				}

				//PokiSDK.gameplayStart();
				// your code to continue to game
				//continueToGame();
			}
		); ;
};
