SoundSystem.Update = function() {
	if(SoundSystem.stopMusicFlag) {
		SoundSystem.musicVolume -= 0.04;
		SoundSystem._musicTransform.volume = SoundSystem.musicVolume * SoundSystem.musicVolumeMultiplier;
		if(SoundSystem.musicChannel != null) {
			SoundSystem.musicChannel.set_soundTransform(SoundSystem._musicTransform);
		}
		if(SoundSystem.musicVolume <= 0) {
			SoundSystem.stopMusicFlag = false;
			if(SoundSystem.musicChannel != null) {
				SoundSystem.musicChannel.stop();
			}
		}
	}
	if(SoundSystem.musicChannel != null) {
		if(!SoundSystem.FORCE_LOOP) {
			if(SoundSystem.LastMusicName == "selection") {
				var newPosition = SoundSystem.musicChannel.get_position();
				if(newPosition < SoundSystem.oldLastPosition) {
					SoundSystem.FORCE_LOOP = true;
					SoundSystem.musicChannel = SoundSystem.musicSelection.play(0,10000);
					if(SoundSystem.musicChannel != null) {
						SoundSystem.musicChannel.set_soundTransform(SoundSystem._musicTransform);
					}
				}
				SoundSystem.oldLastPosition = SoundSystem.musicChannel.get_position();
			}
		}
	}
	var _g1 = 0;
	var _g = SoundSystem.sounds.length;
	while(_g1 < _g) {
		var i = _g1++;
		if(SoundSystem.sounds[i] > 0) {
			SoundSystem.sounds[i]--;
		}
	}
	SoundSystem.lastPoint = 0;
	SoundSystem.lastExplosion++;
	if(SoundSystem.lastExplosion > 10) {
		SoundSystem.lastExplosion = 10;
	}
};
SoundSystem.PlayLastMusic = function(_force) {
	if(_force == null) {
		_force = false;
	}
	SoundSystem.PlayMusic(SoundSystem.LastMusicName,-1,_force);
};
SoundSystem.PlayMusic = function(musicName,_time,_forced) {
	if(_forced == null) {
		_forced = false;
	}
	if(_time == null) {
		_time = -1;
	}
	if(SoundSystem._musicTransform == null) {
		return;
	}
	if(!Utils.MusicOn) {
		return;
	}
	if(musicName == SoundSystem.LastMusicName && !_forced) {
		return;
	}
	SoundSystem.last_position = 0;
	if(SoundSystem.stopMusicFlag || Utils.IS_ANDROID) {
		SoundSystem.stopMusicFlag = false;
		if(SoundSystem.musicChannel != null) {
			if(musicName == "selection" && SoundSystem.LastMusicName == "main_menu") {
				SoundSystem.last_position = SoundSystem.musicChannel.get_position();
			}
			SoundSystem.musicChannel.stop();
		}
	}
	if(SoundSystem.musicChannel != null) {
		if(musicName == "selection" && SoundSystem.LastMusicName == "main_menu") {
			SoundSystem.last_position = SoundSystem.musicChannel.get_position();
		}
		if(musicName == "") {
			SoundSystem.StopMusic();
		} else {
			SoundSystem.musicChannel.stop();
		}
	}
	SoundSystem.musicVolume = SoundSystem.MUSIC_VOLUME;
	SoundSystem._musicTransform.volume = SoundSystem.musicVolume * SoundSystem.musicVolumeMultiplier;
	if(SoundSystem.musicChannel != null) {
		SoundSystem.musicChannel.set_soundTransform(SoundSystem._musicTransform);
	}
	SoundSystem.LastMusicName = musicName;
	switch(musicName) {
	case "boss":
		SoundSystem.musicChannel = SoundSystem.musicBoss.play(0,10000);
		if(SoundSystem.musicChannel != null) {
			SoundSystem.musicChannel.set_soundTransform(SoundSystem._musicTransform);
		}
		break;
	case "game_over":
		SoundSystem.musicChannel = SoundSystem.musicGameOver.play(0,1);
		if(SoundSystem.musicChannel != null) {
			SoundSystem.musicChannel.set_soundTransform(SoundSystem._musicTransform);
		}
		break;
	case "bonus":case "death":case "hurry_up":case "intro":case "level":
		SoundSystem.musicChannel = SoundSystem.musicLevel.play(0,10000);
		if(SoundSystem.musicChannel != null) {
			SoundSystem.musicChannel.set_soundTransform(SoundSystem._musicTransform);
		}
		break;
	}
};
