	,bulletToEnemyCollision: function(bullet) {
		if(bullet.isMagicBullet() && !this.IS_IMMUNE_TO_MAGIC_BULLET) {
			Utils.Slot.gameVariables[20]++;
			this.stunHandler.unstun();
			this.setDead(bullet);
			return;
		}
		this.lastBullet = bullet;
		if(js_Boot.__instanceof(bullet.sprite,sprites_bullets_WizardBubbleBulletSprite)) {
			SoundSystem.PlaySound("bullet_impact_enemy");
		}
		var isLeftSide = false;
		var difference;
		if(bullet.heroMidXPosWhenShot < this.getMidXPos()) {
			difference = this.getMidXPos() - bullet.heroMidXPosWhenShot;
			isLeftSide = true;
		} else {
			difference = bullet.heroMidXPosWhenShot - this.getMidXPos();
		}
		game_$utils_PointsManager.AddPoints(3,bullet.PLAYER_ID);
		if(difference <= 22 && this.stateMachine.currentState != "IS_STUNNED_STATE" && this.stateMachine.currentState != "IS_UNSTUNNING_STATE" && this.IS_CLOSED_STUNNED_ALLOWED) {
			bullet.sprite.set_visible(false);
			if(isLeftSide) {
				this.xVel = 2;
			} else {
				this.xVel = -2;
			}
			this.yVel = -4;
			this.stateMachine.performAction("CLOSE_BULLET_HIT_ACTION");
			Utils.Slot.gameVariables[4]++;
			SoundSystem.PlaySound("bullet_close_impact");
			this.level.freezeAction(10);
			this.level.camera.shake(16,false,-1,false);
			var pSprite = new sprites_particles_ImpactParticleSprite();
			if(isLeftSide) {
				this.level.particlesManager.pushParticle(pSprite,this.getMidXPos() - difference * 0.5,this.getMidYPos(),0,0,0);
			} else {
				pSprite.set_scaleX(-1);
				this.level.particlesManager.pushParticle(pSprite,this.getMidXPos() + difference * 0.5,this.getMidYPos(),0,0,0);
			}
		} else {
			this.COLLISION_ID = this.CHECK_COLLISION_ID = -1;
			if(this.stateMachine.currentState != "IS_STUNNED_STATE") {
				Utils.Slot.gameVariables[3]++;
			}
			var tmp = this.stateMachine.currentState != "IS_JUMPING_STUNNED_STATE";
			this.ADD_EXTRA_STUN = false;
			var player_id = bullet.PLAYER_ID;
			if(player_id == 1) {
				this.LAST_PLAYER_ID = 1;
				if(this.level.hero1.isPowerUpActive(entities_Hero.POWER_UP_STUN)) {
					this.ADD_EXTRA_STUN = true;
				}
			} else {
				this.LAST_PLAYER_ID = 2;
				if(this.level.hero2 != null) {
					if(this.level.hero2.isPowerUpActive(entities_Hero.POWER_UP_STUN)) {
						this.ADD_EXTRA_STUN = true;
					}
				}
			}
			this.stateMachine.performAction("BULLET_HIT_ACTION");
		}
	}
