	,update: function() {
		if(this.stunHandler != null) {
			this.stunHandler.update();
		}
		if(this.stateMachine.currentState != "IS_STUNNED_STATE" && this.stateMachine.currentState != "IS_UNSTUNNING_STATE" && this.stateMachine.currentState != "IS_SPAWNING_STATE" && this.stateMachine.currentState != "IS_JUMPING_STUNNED_STATE") {
			this.stun_hits = 0;
		}
		this.last_stun_tick--;
		if(this.last_stun_tick <= 0) {
			this.last_stun_tick = 0;
		}
		this.setHelpFriction();
		this.updateGlitchCheck();
		if(this.BULLET_HIT_FLAG) {
			this.bullet_hit_counter1++;
			var wait_time = 3;
			if(this.sprite.get_visible()) {
				wait_time = 5;
			}
			if(this.bullet_hit_counter1 >= wait_time) {
				this.bullet_hit_counter1 = 0;
				this.bullet_hit_counter2++;
				this.sprite.set_visible(!this.sprite.get_visible());
				if(this.bullet_hit_counter2 > 6) {
					this.sprite.set_visible(true);
					this.BULLET_HIT_FLAG = false;
				}
			}
		}
		if(this.stateMachine.currentState == "IS_STUNNED_STATE") {
			if(Utils.IsTutorial == false) {
				this.stun_counter--;
				if(this.stun_counter <= 0) {
					this.stateMachine.performAction("END_ACTION");
				}
			}
		} else if(this.stateMachine.currentState == "IS_JUMPING_STUNNED_STATE" || this.stateMachine.currentState == "IS_JUMPING_DEAD_STATE") {
			this.counter2++;
			if(this.counter2 < 10) {
				this.gravity_friction = 0;
			} else {
				this.gravity_friction = 0.5;
			}
		} else if(this.stateMachine.currentState == "IS_UNSTUNNING_STATE") {
			this.counter1++;
			if(this.counter1 >= 120) {
				this.lastBullet = null;
				this.unstun();
				this.stateMachine.performAction("END_ACTION");
				this.sprite.set_scaleX(0.75);
				this.sprite.set_scaleY(1.25);
				this.smallJump();
			}
		} else if(this.stateMachine.currentState == "IS_SPAWNING_STATE") {
			this.yVel = 6;
			this.onTop();
			if(this.yPos >= this.originalYPos) {
				this.yPos = this.originalYPos;
				this.yVel = 0;
				this.AVOID_COLLISION_DETECTION = false;
				this.stateMachine.performAction("END_ACTION");
				if(Utils.Slot.gameVariables[30] == Utils.EASY) {
					this.stateMachine.setState("IS_STUNNED_STATE");
				}
			}
		}
		if(this.IS_ANGRY) {
			this.angry_counter_1--;
			if(this.angry_counter_1 < 0) {
				this.angry_counter_1 = 10 + Math.random() * 10 | 0;
				if(this.allowEnemyAngryParticles()) {
					var angry_p_offset = this.getAngryParticleOffset(this.angry_counter_2 == 0 ? false : true);
					var pSprite = new sprites_particles_AngryParticleSprite();
					var particle;
					if(this.angry_counter_2 == 0) {
						this.angry_counter_2 = 1;
						if(Math.random() * 100 > 80) {
							this.angry_counter_2 = 0;
						}
						pSprite.set_scaleX(-1);
						particle = this.level.particlesManager.pushParticle(pSprite,0,0,0,0,1,5,angry_p_offset.x,angry_p_offset.y);
						particle.setEntity(this);
						particle.originalXPos = angry_p_offset.x;
						particle.originalYPos = angry_p_offset.y;
					} else {
						this.angry_counter_2 = 0;
						if(Math.random() * 100 > 80) {
							this.angry_counter_2 = 1;
						}
						pSprite.set_scaleX(1);
						particle = this.level.particlesManager.pushParticle(pSprite,0,0,0,0,1,5,-this.WIDTH * 0.5,0);
						particle.setEntity(this);
						particle.originalXPos = angry_p_offset.x;
						particle.originalYPos = angry_p_offset.y;
					}
				}
			}
		} else if(this.isAngryAllowed()) {
			if(!(this.stateMachine.currentState == "IS_STUNNED_STATE" || this.stateMachine.currentState == "IS_UNSTUNNING_STATE" || this.stateMachine.currentState == "IS_AVALANCHE_STATE" || this.stateMachine.currentState == "IS_DEAD_STATE" || this.stateMachine.currentState == "IS_JUMPING_STUNNED_STATE" || this.stateMachine.currentState == "IS_JUMPING_DEAD_STATE" || this.dead)) {
				if(this.level.enemiesManager.getEnemiesAlive() == 1 && !this.BLOCK_ANGRY && Utils.Slot.gameVariables[55] > 5) {
					this.setAngry();
				}
			}
		}
		if(this.IS_VANISHING) {
			if(this.vanish_counter_2++ > 1) {
				this.vanish_counter_2 = 0;
				this.sprite.set_visible(!this.sprite.get_visible());
				if(this.ghostSprite != null) {
					this.ghostSprite.set_visible(this.sprite.get_visible());
				}
				this.stunHandler.sprite.set_visible(false);
			}
			this.vanish_counter_1++;
			if(this.vanish_counter_1 >= 120) {
				this.dead = true;
			}
		}
		if(Utils.SEA_LEVEL > 0) {
			if(!this.IS_IN_WATER) {
				if(this.getMidYPos() > Utils.SEA_LEVEL) {
					this.setInsideWater();
				}
			} else if(this.getMidYPos() < Utils.SEA_LEVEL) {
				this.setOutsideWater();
			}
		} else if(this.IS_IN_WATER) {
			this.setOutsideWater();
		}
		this.updateTeleport();
		var _friction_1 = 0.15;
		var _friction_2 = 0.5;
		this.scaleXVel += (1 - this.sprite.get_scaleX()) * _friction_1;
		this.scaleYVel += (1 - this.sprite.get_scaleY()) * _friction_1;
		var _g = this.sprite;
		_g.set_scaleX(_g.get_scaleX() + this.scaleXVel);
		var _g1 = this.sprite;
		_g1.set_scaleY(_g1.get_scaleY() + this.scaleYVel);
		this.scaleXVel *= _friction_2;
		this.scaleYVel *= _friction_2;
	}
