			this.xPos = entities_Easings.easeInOutSine(this.t_tick,this.t_start_x,this.t_diff_x,this.t_time);
			this.yPos = entities_Easings.easeInOutSine(this.t_tick,this.t_start_y,this.t_diff_y,this.t_time);
