		SoundSystem.StopMusic(true);
		this.sprite.gfxHandle().gotoAndStop(6 + (this.IS_ANGRY ? this.ANGRY_ANIM_SHIFT : 0));
		this.sprite.gfxHandle().gfxHandleClip().gotoAndPlay(1);
		Utils.Slot.gameVariables[20]++;
		SoundSystem.PlaySound("skull_game_over");
		this.ghostSprite.set_visible(false);
