			this.sprite.gfxHandle().gotoAndStop(4 + ((this.IS_ANGRY ? this.ANGRY_ANIM_SHIFT : 0) | 0));
			this.sprite.gfxHandle().gfxHandleClip().gotoAndPlay(1);
