			particle = this.pushParticle(cSprite,xPos,yPos,Math.sin(rand_dir_angle) * rand_power,Math.cos(rand_dir_angle) * rand_power,0.85 + Math.random() * 0.1,(i1 / 5 | 0) * 2,Math.random() * Math.PI * 2,Math.random() * Math.PI * 2,Math.random() * 30);
			particle.sin_wave_1 = Math.random() * Math.PI * 2;
			particle.sin_wave_2 = 4 + Math.random() * 4;
			cSprite.set_rotation(rand_rot_angle);
			cSprite.set_visible(false);
			particle.DO_NOT_UPDATE = true;
