	,createItemSparkleParticle: function(color,xPos,yPos,amount,entity,_xOffset,_yOffset) {
		if(_yOffset == null) {
			_yOffset = 0;
		}
		if(_xOffset == null) {
			_xOffset = 0;
		}
		var i;
		var step;
		var speed;
		var time = 0;
		var angle = 0;
		var frame_offset = 0;
		var index;
		var pParticle;
		if(amount <= 0) {
			amount = 1;
		}
		step = Math.PI * 2 / amount;
		var _pSprite;
		var _g1 = 0;
		var _g = amount;
		while(_g1 < _g) {
			var i1 = _g1++;
			if(i1 % 2 == 0) {
				index = 1 + frame_offset | 0;
				_pSprite = new sprites_particles_GenericParticleSprite(sprites_particles_GenericParticleSprite.BLUE_SPARKLE);
				if(Math.random() * 100 > 50) {
					_pSprite.gfxHandleClip().gotoAndPlay(1);
				} else {
					_pSprite.gfxHandleClip().gotoAndPlay(2);
				}
				time = 15;
			} else {
				index = 2 + frame_offset | 0;
				_pSprite = new sprites_particles_GenericParticleSprite(sprites_particles_GenericParticleSprite.BLUE_SPARKLE_SMALL);
				if(Math.random() * 100 > 50) {
					_pSprite.gfxHandleClip().gotoAndPlay(1);
				} else {
					_pSprite.gfxHandleClip().gotoAndPlay(2);
				}
				time = 10;
			}
			angle = i1 * step + Math.random() * step;
			speed = 8;
			var damping = 0.7;
			pParticle = this.pushParticle(_pSprite,xPos,yPos,Math.sin(angle) * speed,Math.cos(angle) * speed,damping,time,Math.random() * 15);
			pParticle.originalXPos += _xOffset;
			pParticle.originalYPos += _yOffset;
			pParticle.setEntity(entity);
		}
	}
	,hurtImpactParticle: function(entity,enemy_mid_x,enemy_mid_y) {
		var entity_mid_x = entity.getMidXPos();
		var entity_mid_y = entity.getMidYPos();
		var radius = (entity.WIDTH + entity.HEIGHT) * 0.25;
		var x_diff = enemy_mid_x - entity_mid_x;
		var y_diff = enemy_mid_y - entity_mid_y;
		var distance = Math.sqrt(x_diff * x_diff + y_diff * y_diff);
		x_diff /= distance;
		y_diff /= distance;
		this.pushParticle(new sprites_particles_HurtImpactParticleSprite(),entity_mid_x + x_diff * radius,entity_mid_y + y_diff * radius,0,0,0);
	}
