	,showMessage: function(string,_delay,_duration) {
		if(_duration == null) {
			_duration = 30;
		}
		if(_delay == null) {
			_delay = -1;
		}
		if(string == StringsManager.GetString("hurry")) {
			this.IS_HURRY_MESSAGE = true;
			this.hud_counter1 = this.hud_counter2 = 0;
			this.level.freezeAction(-1);
		} else {
			this.IS_HURRY_MESSAGE = false;
		}
		this.messageTextPanel.updateText(string);
		this.messageTextPanel.set_x((Utils.WIDTH - this.messageTextPanel.WIDTH) * 0.5 | 0);
		this.messageTextPanel.set_y((Utils.HEIGHT - this.messageTextPanel.HEIGHT) * 0.5 | 0);
		this.message_text_delay = _delay;
		this.message_text_duration = _duration;
		if(this.message_text_delay < 1) {
			this.messageTextPanel.set_visible(true);
		} else {
			this.messageTextPanel.set_visible(false);
		}
		this.top_container.setChildIndex(this.messageTextPanel,this.top_container.get_numChildren() - 1);
		if(this.bossLivesPanel.get_visible()) {
			this.SHOW_BOSS_LIVES = true;
			this.bossLivesPanel.set_visible(false);
		} else {
			this.SHOW_BOSS_LIVES = false;
		}
	}
