var interfaces_SoundHud = function(_level) {
	this.level = _level;
	this.hudPanel = new interfaces_panels_SoundHudPanel();
	this.hudPanel.set_x(this.hudPanel.set_y(0));
	this.hudPanel.set_scaleX(this.hudPanel.set_scaleY(Utils.GFX_SCALE));
	Utils.rootMovie.addChild(this.hudPanel);
	this.hudPanel.pauseButton.set_visible(false);
	this.hudPanel.soundOnButton.set_visible(false);
	this.canPause = false;
	Utils.PauseOn = false;
	this.tick = 0;
	this.time = 0.2;
	this.start_y = 0;
	this.diff_y = 0;
	this.delayCounter = this.redBlinkCounter = this.blinkAmount = 0;
};
$hxClasses["interfaces.SoundHud"] = interfaces_SoundHud;
interfaces_SoundHud.__name__ = ["interfaces","SoundHud"];
interfaces_SoundHud.prototype = {
	level: null
	,hudPanel: null
	,canPause: null
	,delayCounter: null
	,redBlinkCounter: null
	,blinkAmount: null
	,tick: null
	,time: null
	,start_y: null
	,diff_y: null
	,destroy: function() {
		if(this.hudPanel.pauseButton.get_visible()) {
			this.hudPanel.pauseButton.removeEventListener("triggered",$bind(this,this.pauseClickHandler));
		}
		this.hudPanel.soundOnButton.removeEventListener("triggered",$bind(this,this.soundOnClickHandler));
		this.hudPanel.soundOffButton.removeEventListener("triggered",$bind(this,this.soundOffClickHandler));
		Utils.rootMovie.removeChild(this.hudPanel);
		this.hudPanel.destroy();
		this.hudPanel.dispose();
		this.hudPanel = null;
		this.level = null;
	}
	,update: function() {
		if(Utils.IS_SCREENSHOT_MODE) {
			this.hudPanel.pauseButton.set_alpha(0);
		}
		if(Utils.SoundOn) {
			this.hudPanel.soundOnButton.set_visible(true);
			this.hudPanel.soundOffButton.set_visible(false);
		} else {
			this.hudPanel.soundOnButton.set_visible(false);
			this.hudPanel.soundOffButton.set_visible(true);
		}
		if(Utils.IS_HTML_5) {
			this.hudPanel.pauseButton.set_visible(true);
		} else {
			this.hudPanel.pauseButton.set_visible(false);
			this.hudPanel.soundOnButton.set_visible(false);
			this.hudPanel.soundOffButton.set_visible(false);
		}
	}
	,enablePause: function() {
		this.canPause = true;
		this.hudPanel.pauseButton.set_touchable(true);
		this.hudPanel.soundOnButton.set_touchable(true);
		this.hudPanel.soundOffButton.set_touchable(true);
	}
	,disablePause: function() {
		this.canPause = false;
		this.hudPanel.pauseButton.set_touchable(false);
		this.hudPanel.soundOnButton.set_touchable(false);
		this.hudPanel.soundOffButton.set_touchable(false);
	}
	,showPause: function() {
		this.hudPanel.pauseButton.set_visible(true);
		this.hudPanel.pauseButton.addEventListener("triggered",$bind(this,this.pauseClickHandler));
		this.hudPanel.soundOnButton.addEventListener("triggered",$bind(this,this.soundOnClickHandler));
		this.hudPanel.soundOffButton.addEventListener("triggered",$bind(this,this.soundOffClickHandler));
	}
	,showHelp: function() {
		this.delayCounter = 0;
		this.hudPanel.soundOnButton.set_y(0);
		this.hudPanel.soundOnButton.set_touchable(true);
	}
	,pauseClickHandler: function(event) {
		if(this.canPause) {
			SoundSystem.PlaySound("select");
			Utils.PauseOn = true;
		}
	}
	,soundOnClickHandler: function(event) {
		Utils.SoundOn = false;
		Utils.MusicOn = false;
		SoundSystem.StopMusic(true,true);
	}
	,soundOffClickHandler: function(event) {
		Utils.SoundOn = true;
		Utils.MusicOn = true;
		SoundSystem.PlayLastMusic(true);
	}
	,__class__: interfaces_SoundHud
};
