var interfaces_buttons_MagicButton = function(_level,_WIDTH,_HEIGHT) {
	this.level = _level;
	this.WIDTH = _WIDTH | 0;
	this.HEIGHT = _HEIGHT | 0;
	this.FULL_HEIGHT = this.HEIGHT - 10 | 0;
	this.REDRAW_FLAG = false;
	this.upTexture = null;
	this.downTexture = null;
	this.createUpTexture();
	this.createDownTexture();
	starling_display_Button.call(this,this.upTexture,"",this.downTexture);
	this.magicMeter = new sprites_hud_MagicMeterHudSprite();
	this.magicMeter.set_x(5);
	this.magicMeter.set_y(5);
	this.magicMeter.set_width(this.WIDTH - 10);
	this.magicMeter.set_height(this.FULL_HEIGHT);
	this.addChild(this.magicMeter);
	this.magicMeter.gfxHandleClip().gotoAndStop(1);
	this.magicImage = new starling_display_Image(TextureManager.hudTextureAtlas.getTexture("magic_icon"));
	this.magicImage.set_touchable(false);
	this.addChild(this.magicImage);
	this.magicImage.set_x((this.WIDTH - this.magicImage.get_width()) * 0.5 | 0);
	this.magicImage.set_y((this.HEIGHT - this.magicImage.get_height()) * 0.5 | 0);
	this.turnOffButton();
	this.updateLevels(true);
	this.addEventListener("triggered",$bind(this,this.magicClick));
};
