		var MAX_ENEMIES = 20;
		var ENEMIES_DIFF = MAX_ENEMIES - MIN_ENEMIES | 0;
		var MAX_MAGIC_POWER = 1.44;
		var MIN_MAGIC_POWER = 0.8;
		var MAGIC_DIFF = MAX_MAGIC_POWER - MIN_MAGIC_POWER;
		var MAGIC_LEVEL = 1;
		MAGIC_LEVEL -= MIN_MAGIC_POWER;
