	,levelCompleteState: function() {
		this.enemiesManager.resetHurryUp();
		if(this.isPerfectLevel) {
			if(Utils.Slot.gameVariables[37] != Utils.Slot.gameVariables[55]) {
				Utils.Slot.gameVariables[37] = Utils.Slot.gameVariables[55];
				Utils.Slot.gameVariables[44]++;
			}
			if(Utils.IsBossLevel()) {
				Utils.Slot.gameVariables[50]++;
			}
		} else {
			Utils.Slot.gameVariables[44] = 0;
			Utils.Slot.gameVariables[36] = 0;
		}
		Utils.Slot.gameVariables[43] = 0;
		this.itemsManager.setLevelCompleteCounter();
		this.bulletsManager.levelCompleteState();
		this.collisionsManager.levelCompleteState();
		this.isPerfectLevel = true;
		this.counter1 = this.counter2 = 0;
	}
