	,getGradientColor: function(hex,hex2,ratio) {
		var r = hex >> 16;
		var g = (hex >> 8 | 0) & 255;
		var b = hex & 255;
		r += ((hex2 >> 16) - r) * ratio | 0;
		g += (((hex2 >> 8 | 0) & 255) - g) * ratio | 0;
		b += ((hex2 & 255) - b) * ratio | 0;
		return r << 16 | g << 8 | b | 0;
	}
