		this.standAnimation.set_touchable(false);
		this.standAnimation.set_pivotX(4);
		this.standAnimation.set_pivotY(4);
		this.standAnimation.set_loop(true);
		this.standAnimation.gotoAndPlay((Math.random() * this.standAnimation.get_numFrames() | 0) + 1);
