	,keyDownListener: function(event) {
		if(this.intro_counter_1 < 60 || this.ALREADY_OUT) {
			return;
		}
		Utils.CONTROLLER_TYPE = Utils.KEYBOARD;
		var keyCode = event.get_keyCode();
		if(keyCode == 32 || keyCode == Utils.KEY_ENTER) {
			if(!this.ALREADY_OUT) {
				this.ALREADY_OUT = true;
				this.INPUT_QUIT = true;
				this.GET_OUT_FLAG = true;
				this.choice = 1;
				SoundSystem.StopMusic(false);
				SoundSystem.PlaySound("select");
			}
		}
	}
	,intro_gamepadInputDownListener: function(event) {
		if(this.intro_counter_1 < 60 || this.ALREADY_OUT) {
			return;
		}
		Utils.CONTROLLER_TYPE = Utils.GAMEPAD;
		var keyCode = event.keyCode;
		if(keyCode == game_$utils_GamepadEvent.BUTTON_A || keyCode == game_$utils_GamepadEvent.BUTTON_X) {
			if(!this.ALREADY_OUT) {
				this.ALREADY_OUT = true;
				this.GET_OUT_FLAG = true;
				this.choice = 1;
				SoundSystem.StopMusic(false);
				SoundSystem.PlaySound("select");
			}
		}
	}
	,onClick: function(event) {
		if(this.intro_counter_1 < 60 || this.ALREADY_OUT) {
			return;
		}
		var touch = event.getTouch(Utils.rootStage);
		if(touch != null) {
			if(touch.get_phase() == "ended") {
				if(!this.ALREADY_OUT) {
					this.ALREADY_OUT = true;
					this.GET_OUT_FLAG = true;
					this.choice = 1;
					SoundSystem.StopMusic(false);
					SoundSystem.PlaySound("select");
				}
			}
		}
	}
