		this.container = new starling_display_Sprite();
		this.container.set_x(this.container.set_y(0));
		Utils.rootMovie.addChild(this.container);
		var amount_w = Utils.SCREEN_WIDTH / 320;
		var amount_h = Utils.SCREEN_HEIGHT / 282;
		if(amount_h < amount_w) {
			this.scale = amount_h | 0;
			if(amount_h < 1) {
				this.scale = 0.5;
			}
		} else {
			this.scale = amount_w | 0;
			if(amount_w < 1) {
				this.scale = 0.5;
			}
		}
		if(this.scale <= 0) {
			this.scale = 1;
		}
		this.whiteBackground = new starling_display_Quad(Utils.SCREEN_WIDTH,Utils.SCREEN_HEIGHT,2110331);
		this.whiteBackground.set_x(this.whiteBackground.set_y(0));
		this.container.addChild(this.whiteBackground);
		this.logoShadow = new starling_display_Image(TextureManager.introTextureAtlas.getTexture("neutronizedLogoShadow"));
		this.logoShadow.set_pivotX(this.logoShadow.get_width() * 0.5);
		this.logoShadow.set_pivotY(this.logoShadow.get_height() * 0.5);
		this.logoShadow.set_scaleX(this.logoShadow.set_scaleY(this.scale));
		this.logoShadow.set_x(Utils.SCREEN_WIDTH * 0.5);
		this.logoShadow.set_y(Utils.SCREEN_HEIGHT * 0.5 + 8 * this.scale);
		this.logoShadow.set_alpha(0);
		this.container.addChild(this.logoShadow);
