	,introShortcutState: function() {
		this.counter_1 = this.counter_2 = 0;
		this.whiteFadeImage.set_visible(true);
		SoundSystem.StopMusic();
		SoundSystem.PlayMusic("splash");
	}
	,normalState: function() {
		this.enableButtons(true);
		this.counter_1 = this.counter_2 = this.counter_3 = 0;
	}
	,playState: function() {
		SoundSystem.StopMusic();
		if(Utils.Slot.gameVariables[58] == 0) {
			Utils.StartNewTutorialGame();
			this.choice = 4;
		} else if(this.IS_DRAGON_CLICKED) {
			this.choice = 4;
		} else {
			this.choice = 0;
		}
		this.counter_1 = this.counter_2 = 0;
		this.brightness = 1;
		this.enableButtons(false);
		this.playPanel.blink();
	}
	,settingsState: function() {
		this.choice = 3;
		this.enableButtons(false);
	}
	,bookState: function() {
		this.choice = 2;
		this.enableButtons(false);
	}
	,cutsceneState: function() {
		this.scale_tick = 1;
	}
