	,updateState: function(game) {
		if(Utils.IS_HTML_5 == false) {
			if(this.music_counter > -1) {
				this.music_counter++;
				if(this.music_counter == 80) {
					SoundSystem.PlayMusic("main_menu");
				}
			}
		}
		if(this.whitePanel.get_visible()) {
			if(this.white_panel_delay++ > 2) {
				var _g = this.whitePanel;
				_g.set_alpha(_g.get_alpha() * 0.75);
				if(this.whitePanel.get_alpha() <= 0.1) {
					this.whitePanel.set_visible(false);
				}
			}
		}
		this.normal_delay++;
		this.intro_counter_1++;
		this.menuBackgroundSplash.update();
		this.playPanel.update();
		if(this.stateMachine.currentState == "IS_NORMAL_STATE") {
			if(Utils.IS_HTML_5 == false) {
				this.counter_1++;
				if(this.counter_1 >= 900) {
					this.choice = 1;
					this.stateMachine.performAction("QUIT_ACTION");
				}
			}
		} else if(this.stateMachine.currentState == "IS_PLAY_STATE") {
			if(this.splashMenuPanel != null) {
				this.splashMenuPanel.update();
			}
			this.counter_1++;
			this.counter_2++;
			if(this.counter_1 >= 3) {
				this.counter_1 = 0;
				if(this.brightness > 0) {
					this.brightness -= 0.2;
					if(this.brightness <= 0) {
						this.brightness = 0;
						if(this.gameTitle.get_filter() != null) {
							this.gameTitle.get_filter().dispose();
							this.gameTitle.set_filter(null);
						}
					} else {
						(js_Boot.__cast(this.gameTitle.get_filter() , starling_filters_ColorMatrixFilter)).reset();
						(js_Boot.__cast(this.gameTitle.get_filter() , starling_filters_ColorMatrixFilter)).adjustBrightness(this.brightness);
					}
				}
			}
			if(this.counter_2 >= 60) {
				this.choice = 0;
				this.stateMachine.performAction("QUIT_ACTION");
			}
		} else if(this.stateMachine.currentState == "IS_MENU_STATE") {
			if(this.splashMenuPanel != null) {
				this.splashMenuPanel.update();
			}
		} else if(this.stateMachine.currentState == "IS_BOOK_STATE") {
			this.stateMachine.performAction("QUIT_ACTION");
		} else if(this.stateMachine.currentState == "IS_SETTINGS_STATE") {
			this.stateMachine.performAction("QUIT_ACTION");
		}
		game.updateTempSplashState();
	}
